import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const pkgPath = resolve(ROOT, "package.json");
const envPath = resolve(ROOT, ".env.local");

const KEY_LINE_PREFIX = "NEXT_PUBLIC_APP_VERSION=";

const pkg = JSON.parse(readFileSync(pkgPath, "utf8"));
const version = String(pkg.version || "0.0.0").trim();

const HEADER =
  "# ----- Generated by scripts/write-app-version-env.mjs -----";
const FOOTER = "# ----- end generated -----";
const block = [
  HEADER,
  "# Drives the in-app update banner shown to Android APK users.",
  `${KEY_LINE_PREFIX}${version}`,
  FOOTER,
].join("\n");

function rewriteEnv() {
  if (!existsSync(envPath)) {
    mkdirSync(ROOT, { recursive: true });
    writeFileSync(envPath, `${block}\n`, "utf8");
    return;
  }
  const raw = readFileSync(envPath, "utf8");
  const re = new RegExp(
    `${HEADER.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}[\\s\\S]*?${FOOTER.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\n?`,
    "m"
  );
  const withExistingBlockReplaced = re.test(raw)
    ? raw.replace(re, `${block}\n`)
    : null;

  const versionLineRe = new RegExp(`^${KEY_LINE_PREFIX.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}.*$`, "m");
  const withVersionLineReplaced =
    !withExistingBlockReplaced && versionLineRe.test(raw)
      ? raw.replace(versionLineRe, `${KEY_LINE_PREFIX}${version}`)
      : null;

  const out = withExistingBlockReplaced ??
    withVersionLineReplaced ??
    (raw.endsWith("\n") ? `${raw}${block}\n` : `${raw}\n${block}\n`);

  writeFileSync(envPath, out, "utf8");
}

rewriteEnv();
console.log(`Wrote NEXT_PUBLIC_APP_VERSION=${version} into ${envPath}`);
